mapper.select:
SELECT MAX(registrationNo)
FROM bq_registration
WHERE deleted = 0
  AND orderTime >= #{todayStart}
  AND orderTime < #{todayEnd}
  AND registrationNo IS NOT NULL

SELECT r.id, r.orderTime, r.patient, r.gender, r.age, r.ageType, p.idCard, p.mobile, p.address, r.doctor, r.isFirstVisit, r.status FROM bq_registration r LEFT JOIN bq_patient p ON p.name = r.patient AND p.deleted = 0 WHERE r.deleted = 0
AND r.patient LIKE CONCAT('%', #{patientName}, '%')
AND r.doctor = #{doctor}
AND r.orderTime >= #{startTime}
AND r.orderTime <= #{endTime}
ORDER BY r.orderTime DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM bq_registration r
LEFT JOIN bq_patient p ON p.name = r.patient AND p.deleted = 0
WHERE r.deleted = 0

    AND r.patient LIKE CONCAT('%', #{patientName}, '%')


    AND r.doctor = #{doctor}


    AND r.orderTime >= #{startTime}


    AND r.orderTime <= #{endTime}

SELECT r.id, p.name AS patient, p.gender, p.firstAge, p.lastAge, p.ageType, r.registrationNo, r.department, r.doctor, r.clinic, r.totalPrice, r.registrationType, r.outpatientType, r.isFirstVisit, r.orderTime, r.status, r.patientId, r.age, r.statusFee, r.deleted, r.createdTime, r.updatedTime, r.createdBy, r.updatedBy FROM bq_registration r LEFT JOIN bq_patient p ON p.id = r.patientId AND p.deleted = 0 WHERE r.deleted = 0
AND p.name LIKE CONCAT('%', #{patientName}, '%')
AND r.orderTime >= #{startTime}
AND r.orderTime <= #{endTime}
AND r.status = #{status}
ORDER BY r.createdTime DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM bq_registration r
LEFT JOIN bq_patient p ON p.id = r.patientId AND p.deleted = 0
WHERE r.deleted = 0

    AND p.name LIKE CONCAT('%', #{patientName}, '%')


    AND r.orderTime >= #{startTime}


    AND r.orderTime <= #{endTime}


    AND r.status = #{status}
